import{_ as t,o as a,c as o,a2 as n}from"./chunks/framework.CsGzzEsd.js";const u=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[],"relativePath":"blogs/CFA/Quiz/C2 Economics/misses.md","filePath":"blogs/CFA/Quiz/C2 Economics/misses.md"}'),r={name:"blogs/CFA/Quiz/C2 Economics/misses.md"};function s(i,e,g,p,h,d){return a(),o("div",null,[...e[0]||(e[0]=[n('<h2 id="_2026-10-13-—-steady-state" tabindex="-1">2026-10-13 — Steady state <a class="header-anchor" href="#_2026-10-13-—-steady-state" aria-label="Permalink to &quot;2026-10-13 — Steady state&quot;">​</a></h2><p><strong>Q:</strong> When does capital deepening stop? Relate (sy) to required investment.</p><p><strong>Covered:</strong> Steady state is where (sy = sAk^{\\alpha}) equals (\\bigl(\\frac{\\theta}{1-\\alpha}+\\delta+n\\bigr)k). Capital deepening stops at (k^*).</p><p><strong>Gap:</strong> Pin the intersection of the savings curve and the required-investment ray, not a verbal “equilibrium” without the two sides.</p><p>Source: Animus quiz handoff (after the quiz, not mid-quiz).</p><h2 id="_2026-10-13-—-saving-rate" tabindex="-1">2026-10-13 — Saving rate <a class="header-anchor" href="#_2026-10-13-—-saving-rate" aria-label="Permalink to &quot;2026-10-13 — Saving rate&quot;">​</a></h2><p><strong>Q:</strong> What does a higher saving rate do to steady-state (k) and (y), and to long-run growth of (y)?</p><p><strong>Covered:</strong> (\\uparrow s) raises (k^<em>) and (y^</em>) (a <strong>level</strong> effect). Long-run growth of (y) is <strong>not</strong> permanently higher. (s\\in[0,1]) caps how far the lift can go.</p><p><strong>Gap:</strong> Separate the level shift from a permanent growth-rate shift, and remember the (s\\le 1) ceiling.</p><p>Source: Animus quiz handoff (after the quiz, not mid-quiz).</p><h2 id="_2026-10-13-—-convergence" tabindex="-1">2026-10-13 — Convergence <a class="header-anchor" href="#_2026-10-13-—-convergence" aria-label="Permalink to &quot;2026-10-13 — Convergence&quot;">​</a></h2><p><strong>Q:</strong> Country A has potential GDP growth well above (G^<em>); Country B is near (G^</em>). Where does each country’s growth come from?</p><p><strong>Covered:</strong> A ((G &gt; G^<em>)) is still converging via <strong>capital deepening</strong>. B near (G^</em>) gets growth mostly from <strong>TFP</strong> (and labor), not from capital investment.</p><p><strong>Gap:</strong> Map “above steady-state growth” to ongoing capital deepening, and “at (G^*)” to TFP/labor.</p><p>Source: Animus quiz handoff (after the quiz, not mid-quiz).</p><h2 id="_2026-10-13-—-labor-growth" tabindex="-1">2026-10-13 — Labor growth <a class="header-anchor" href="#_2026-10-13-—-labor-growth" aria-label="Permalink to &quot;2026-10-13 — Labor growth&quot;">​</a></h2><p><strong>Q:</strong> What happens to steady-state (k) and (y) when labor-force growth (n) rises?</p><p><strong>Covered:</strong> (\\uparrow n) steepens the required-investment line, so equilibrium (k^<em>) and (y^</em>) fall.</p><p><strong>Gap:</strong> (n) enters the ray’s slope, not the savings curve — the intersection moves left and down.</p><p>Source: Animus quiz handoff (after the quiz, not mid-quiz).</p><h2 id="_2026-10-13-—-tfp-vs-deepening" tabindex="-1">2026-10-13 — TFP vs deepening <a class="header-anchor" href="#_2026-10-13-—-tfp-vs-deepening" aria-label="Permalink to &quot;2026-10-13 — TFP vs deepening&quot;">​</a></h2><p><strong>Q:</strong> What shifts the production curve, and what only moves along it?</p><p><strong>Covered:</strong> Higher (A) (TFP) and (\\alpha) shape or shift the curve. Capital deepening moves <strong>along</strong> a given curve.</p><p><strong>Gap:</strong> Do not call a move along (y=Ak^{\\alpha}) a TFP shift.</p><p>Source: Animus quiz handoff (after the quiz, not mid-quiz).</p>',25)])])}const c=t(r,[["render",s]]);export{u as __pageData,c as default};
